#include "tgcloud/manifest/link_crypto.hpp"
#include <openssl/evp.h>
#include <random>
#include <stdexcept>
namespace tgcloud::manifest {std::string link_encrypt(std::string_view in,std::string_view pw){unsigned char salt[16],iv[16],key[32];std::random_device r;for(auto&x:salt)x=r();for(auto&x:iv)x=r();PKCS5_PBKDF2_HMAC(pw.data(),pw.size(),salt,16,10000,EVP_sha256(),32,key);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_EncryptInit_ex(c,EVP_aes_256_cbc(),nullptr,key,iv);std::string e(in.size()+16,0);int n=0,z=0;EVP_EncryptUpdate(c,(unsigned char*)e.data(),&n,(const unsigned char*)in.data(),in.size());EVP_EncryptFinal_ex(c,(unsigned char*)e.data()+n,&z);EVP_CIPHER_CTX_free(c);std::string o((char*)salt,16);o.append((char*)iv,16);o.append(e.data(),n+z);return o;}std::string link_decrypt(std::string_view b,std::string_view pw){if(b.size()<33)throw std::runtime_error("invalid link");unsigned char key[32];PKCS5_PBKDF2_HMAC(pw.data(),pw.size(),(const unsigned char*)b.data(),16,10000,EVP_sha256(),32,key);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_DecryptInit_ex(c,EVP_aes_256_cbc(),nullptr,key,(const unsigned char*)b.data()+16);std::string p(b.size()-32,0);int n=0,z=0;EVP_DecryptUpdate(c,(unsigned char*)p.data(),&n,(const unsigned char*)b.data()+32,b.size()-32);if(EVP_DecryptFinal_ex(c,(unsigned char*)p.data()+n,&z)<=0){EVP_CIPHER_CTX_free(c);throw std::runtime_error("link decryption failed");}EVP_CIPHER_CTX_free(c);p.resize(n+z);return p;}}
